package com.fasterxml.jackson.core.base;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser.Feature;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.core.util.VersionUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ParserMinimalBase.getValueAsString(String).
 * Since ParserMinimalBase is an abstract class, we use Mockito to create a spy/mock 
 * to control the protected field _currToken and abstract methods like getText().
 */
public class ParserMinimalBase_getValueAsString_TriageGen1Test {

    private ParserMinimalBase parser;

    @Before
    public void setUp() {
        // ParserMinimalBase is abstract, so we mock it.
        // We use Mockito to mock the behavior of the abstract methods.
        parser = Mockito.mock(ParserMinimalBase.class, Mockito.withSettings()
                .useConstructor()
                .defaultAnswer(Mockito.CALLS_REAL_METHODS));
    }

    /**
     * Helper to set the protected field _currToken using reflection, 
     * as it is not directly accessible in the test class.
     */
    private void setCurrToken(JsonToken token) throws Exception {
        java.lang.reflect.Field field = ParserMinimalBase.class.getDeclaredField("_currToken");
        field.setAccessible(true);
        field.set(parser, token);
    }

    @Test
    public void testGetValueAsString_WhenTokenIsValueString() throws Exception {
        // Branch 1: if (_currToken == JsonToken.VALUE_STRING)
        setCurrToken(JsonToken.VALUE_STRING);
        String expectedText = "hello";
        when(parser.getText()).thenReturn(expectedText);

        String result = parser.getValueAsString("default");

        assertEquals(expectedText, result);
    }

    @Test
    public void testGetValueAsString_WhenTokenIsNull() throws Exception {
        // Branch 2: if (_currToken == null ...)
        setCurrToken(null);
        String defaultValue = "default";

        String result = parser.getValueAsString(defaultValue);

        assertEquals(defaultValue, result);
    }

    @Test
    public void testGetValueAsString_WhenTokenIsValueNull() throws Exception {
        // Branch 2: if (_currToken == JsonToken.VALUE_NULL ...)
        setCurrToken(JsonToken.VALUE_NULL);
        String defaultValue = "default";

        String result = parser.getValueAsString(defaultValue);

        assertEquals(defaultValue, result);
    }

    @Test
    public void testGetValueAsString_WhenTokenIsNotScalarValue() throws Exception {
        // Branch 2: if (!_currToken.isScalarValue())
        // JsonToken.START_OBJECT is not a scalar value
        setCurrToken(JsonToken.START_OBJECT);
        String defaultValue = "default";

        String result = parser.getValueAsString(defaultValue);

        assertEquals(defaultValue, result);
    }

    @Test
    public void testGetValueAsString_WhenTokenIsScalarButNotString() throws Exception {
        // Branch 3: return getText() (e.g., VALUE_NUMBER_INT is a scalar)
        setCurrToken(JsonToken.VALUE_NUMBER_INT);
        String expectedText = "123";
        when(parser.getText()).thenReturn(expectedText);

        String result = parser.getValueAsString("default");

        assertEquals(expectedText, result);
    }

    @Test
    public void testGetValueAsString_WhenTokenIsValueBoolean() throws Exception {
        // Branch 3: return getText() (e.g., VALUE_TRUE is a scalar)
        setCurrToken(JsonToken.VALUE_TRUE);
        String expectedText = "true";
        when(parser.getText()).thenReturn(expectedText);

        String result = parser.getValueAsString("default");

        assertEquals(expectedText, result);
    }

    @Test(expected = IOException.class)
    public void testGetValueAsString_WhenGetTextThrowsIOException() throws Exception {
        // Test exception propagation
        setCurrToken(JsonToken.VALUE_STRING);
        when(parser.getText()).thenThrow(new IOException("Simulated IO error"));

        parser.getValueAsString("default");
    }
}
